SELECT T6.TRADE_CALENDAR_ID tradeCalendarId, T6.CALENDARNAME calendarName, group_concat(T6.CALENDARTYPE order by T6.CALENDARTYPE separator ',') calendarType FROM( SELECT T5.TRADE_CALENDAR_ID, T5.CALENDAR_ID, T5.CALENDARNAME, T5.CALENDARTYPE FROM( SELECT T3.TRADE_CALENDAR_ID, T3.CALENDAR_ID, T3.CALENDAR_NAME CALENDARNAME, T4.CALENDAR_NAME CALENDARTYPE FROM( SELECT T1.TRADE_CALENDAR_ID, T1.CALENDAR_ID, T2.CALENDAR_NAME FROM MST_TRADE_CALENDAR T1 LEFT JOIN MST_CALENDAR_INFO T2 ON T1.TRADE_CALENDAR_ID = T2.CALENDAR_ID WHERE T2.IS_TRADE_CALENDAR= #{YESORNO_YES_01,jdbcType=VARCHAR})T3 LEFT JOIN MST_CALENDAR_INFO T4 ON T4.CALENDAR_ID = T3.CALENDAR_ID AND T4.IS_TRADE_CALENDAR != #{YESORNO_YES_01,jdbcType=VARCHAR})T5 WHERE T5.TRADE_CALENDAR_ID IN( SELECT T6.TRADE_CALENDAR_ID FROM MST_TRADE_CALENDAR T6
T6.CALENDAR_ID IN
#{calendarType,jdbcType=VARCHAR}
AND T5.CALENDARNAME LIKE concat(concat('%', #{calendarName,jdbcType=VARCHAR}),'%')
) )T6 GROUP BY T6.TRADE_CALENDAR_ID,T6.CALENDARNAME ORDER BY T6.TRADE_CALENDAR_ID DESC

SELECT CDATE cDate, (case when sum(IS_HOLIDAY) > 0 then '节假日' else '工作日' end)isHoliday FROM MST_HOLIDAY WHERE CALENDAR_ID IN( SELECT CALENDAR_ID FROM MST_TRADE_CALENDAR WHERE TRADE_CALENDAR_ID = #{tradeCalendarId,jdbcType = VARCHAR}) AND DATE_FORMAT(CDATE,'%Y-%m-%d') BETWEEN #{startCDate} AND #{endCDate}
AND IS_HOLIDAY = (CASE WHEN #{isHoliday} ='Y' THEN 1 WHEN 'N' THEN 0 END)
GROUP BY CDATE
